def price(model, usage):
    rates = {"claude-opus-5-5": (4, 20), "claude-sonnet-5-5": (2, 10),
             "claude-haiku-5-5": (0.1, 0.5)}
    rate_in, rate_out = rates[model]
    return (usage.input_tokens * rate_in + usage.output_tokens * rate_out) / 1e6


def _create(*, model, max_tokens, messages, system=None, **kwargs):
    ticket = messages[-1]["content"]
    number = next(w for w in ticket.split() if w.isdigit())
    text = f"Order {number}: customer wants a replacement or refund."
    usage = NS(input_tokens=60, output_tokens=20)
    return NS(content=[NS(type="thinking", thinking=""), NS(type="text", text=text)],
              usage=usage, stop_reason="end_turn")


class _Anthropic:
    def __init__(self, **kwargs):
        self.messages = NS(create=_create)


sys.modules["anthropic"] = NS(Anthropic=_Anthropic)
